        ResumoRequest request = new ResumoRequest(
                List.of(item("Camiseta", "79.90", 1, "0.30")), "MODALIDADE_INEXISTENTE", "CUPOM_INEXISTENTE",
                "FORMA_INEXISTENTE", 1, "PLATINA", "PLANETA");

